import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 4 复习与自测 · 第80–86课","description":"L73–L96 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 4 复习与自测 · 第80–86课","description":"L73–L96 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-04/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 4 复习与自测","summary":"L73–L96 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第73–79课","link":"/life/english/new-concept/book-1/unit-04/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第87–93课","link":"/life/english/new-concept/book-1/unit-04/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第73–79课","link":"/life/english/new-concept/book-1/unit-04/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 4 复习与自测 · 第87–93课","link":"/life/english/new-concept/book-1/unit-04/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/review-part-02.md","filePath":"life/english/new-concept/book-1/unit-04/review-part-02.md"}'),n={name:"life/english/new-concept/book-1/unit-04/review-part-02.md"};function r(l,e,i,h,d,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-单元-4-复习与自测-·-第80–86课" tabindex="-1">第一册：英语初阶 · 单元 4 复习与自测 · 第80–86课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-4-复习与自测-·-第80–86课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 4 复习与自测 · 第80–86课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-04/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-80-·-need-与-must" tabindex="-1">Lesson 80 · need 与 must <a class="header-anchor" href="#lesson-80-·-need-与-must" aria-label="Permalink to &quot;Lesson 80 · need 与 must {#lesson-80-·-need-与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She must go to the pharmacy before six.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>删去多余词：She must to go now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She must go now.</p><p><strong>解析：</strong> 按本课规则判断：need 作实义动词时，可接名词或 to do：need some rice、need to buy rice。第三人称用 needs，否定借助 don&#39;t/doesn&#39;t。must 是情态动词，直接加原形，不加 to。needn&#39;t 是“不必”，其后直接接动词原形。学习时先确定用的是实义动词 need 还是情态表达，避免混用句式。</p></details><p><strong>表达迁移：</strong> 围绕“根据购物清单表达需要去哪里”写两至三句，再读给同伴听。至少使用一次need 与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She must go to the pharmacy before six. We need to buy rice and tomatoes.</p><p>She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。 Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-080">回看本课</a></p><h2 id="lesson-81-·-have-had-的活动用法" tabindex="-1">Lesson 81 · have/had 的活动用法 <a class="header-anchor" href="#lesson-81-·-have-had-的活动用法" aria-label="Permalink to &quot;Lesson 81 · have/had 的活动用法 {#lesson-81-·-have-had-的活动用法}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had vegetable soup for lunch.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填过去式：We ___ (have) soup yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：have 不只表示拥有，也可与 meal、bath、rest 等组成活动短语。have lunch 表吃午饭，have a rest 表休息。一般过去时用 had，问句中 did 后仍用 have。三餐名词单独表示吃饭时常不加冠词，但有修饰语时可说 a good lunch；不能把所有 have + 名词都直译成“拥有”。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去吃喝和日常活动”写两至三句，再读给同伴听。至少使用一次have/had 的活动用法，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We had vegetable soup for lunch. Did you have a good rest after the journey?</p><p>Had 是 have 的过去式，此处表示吃喝；vegetable soup 为食物对象，for lunch 表午餐所用。 Did 构成过去问句，have 恢复原形；a good rest 表一次充分休息，after the journey 表先后关系。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-081">回看本课</a></p><h2 id="lesson-82-·-have-had-的活动用法" tabindex="-1">Lesson 82 · have/had 的活动用法 <a class="header-anchor" href="#lesson-82-·-have-had-的活动用法" aria-label="Permalink to &quot;Lesson 82 · have/had 的活动用法 {#lesson-82-·-have-had-的活动用法}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Did you have a good rest after the journey?</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>填原形：Did you ___ (have) lunch?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：have 不只表示拥有，也可与 meal、bath、rest 等组成活动短语。have lunch 表吃午饭，have a rest 表休息。一般过去时用 had，问句中 did 后仍用 have。三餐名词单独表示吃饭时常不加冠词，但有修饰语时可说 a good lunch；不能把所有 have + 名词都直译成“拥有”。</p></details><p><strong>表达迁移：</strong> 围绕“描述过去吃喝和日常活动”写两至三句，再读给同伴听。至少使用一次have/had 的活动用法，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Did you have a good rest after the journey? We had vegetable soup for lunch.</p><p>Did 构成过去问句，have 恢复原形；a good rest 表一次充分休息，after the journey 表先后关系。 Had 是 have 的过去式，此处表示吃喝；vegetable soup 为食物对象，for lunch 表午餐所用。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-082">回看本课</a></p><h2 id="lesson-83-·-现在完成时入门" tabindex="-1">Lesson 83 · 现在完成时入门 <a class="header-anchor" href="#lesson-83-·-现在完成时入门" aria-label="Permalink to &quot;Lesson 83 · 现在完成时入门 {#lesson-83-·-现在完成时入门}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I have already packed my suitcase.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>补助动词：I ___ already packed.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：现在完成时由 have/has + 过去分词构成，常把过去完成的动作与现在结果联系起来。already 常用于肯定句，yet 常用于疑问或否定句末。问句将 have/has 提前。pack→packed 是规则变化；have 的过去分词是 had，所以 Have you had lunch? 中两个 have 作用不同。不要省略助动词。</p></details><p><strong>表达迁移：</strong> 围绕“出发前检查已经完成的准备”写两至三句，再读给同伴听。至少使用一次现在完成时入门，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I have already packed my suitcase. Have you checked the train times yet?</p><p>I have packed 构成现在完成时，already 常放在助动词与分词之间；当前结果是行李已收拾好。 Have 前置，checked 为过去分词；yet 位于句末，询问截至现在是否已完成核查。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-083">回看本课</a></p><h2 id="lesson-84-·-现在完成时入门" tabindex="-1">Lesson 84 · 现在完成时入门 <a class="header-anchor" href="#lesson-84-·-现在完成时入门" aria-label="Permalink to &quot;Lesson 84 · 现在完成时入门 {#lesson-84-·-现在完成时入门}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Have you checked the train times yet?</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填过去分词：Have you ___ (check) the times?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> checked</p><p><strong>解析：</strong> 按本课规则判断：现在完成时由 have/has + 过去分词构成，常把过去完成的动作与现在结果联系起来。already 常用于肯定句，yet 常用于疑问或否定句末。问句将 have/has 提前。pack→packed 是规则变化；have 的过去分词是 had，所以 Have you had lunch? 中两个 have 作用不同。不要省略助动词。</p></details><p><strong>表达迁移：</strong> 围绕“出发前检查已经完成的准备”写两至三句，再读给同伴听。至少使用一次现在完成时入门，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Have you checked the train times yet? I have already packed my suitcase.</p><p>Have 前置，checked 为过去分词；yet 位于句末，询问截至现在是否已完成核查。 I have packed 构成现在完成时，already 常放在助动词与分词之间；当前结果是行李已收拾好。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-084">回看本课</a></p><h2 id="lesson-85-·-have-been-to-与过去时间" tabindex="-1">Lesson 85 · have been to 与过去时间 <a class="header-anchor" href="#lesson-85-·-have-been-to-与过去时间" aria-label="Permalink to &quot;Lesson 85 · have been to 与过去时间 {#lesson-85-·-have-been-to-与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I have been to Vienna twice.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>填 been/gone：去过且已回来，I have ___ to Vienna.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 按本课规则判断：have been to 表示去过并已返回的经历；have gone to 通常表示去了且尚未返回。谈经验可用现在完成时，补充明确结束的日期或年份时通常改一般过去时。I have been to Rome 与 I went there in 2022 可在一段话中衔接。不能把现在完成时直接与 yesterday 等已结束时间机械拼接。</p></details><p><strong>表达迁移：</strong> 围绕“表达旅行经历并补充具体时间”写两至三句，再读给同伴听。至少使用一次have been to 与过去时间，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I have been to Vienna twice. Rita has gone to the bank and will be back soon.</p><p>Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。 Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-085">回看本课</a></p><h2 id="lesson-86-·-have-been-to-与过去时间" tabindex="-1">Lesson 86 · have been to 与过去时间 <a class="header-anchor" href="#lesson-86-·-have-been-to-与过去时间" aria-label="Permalink to &quot;Lesson 86 · have been to 与过去时间 {#lesson-86-·-have-been-to-与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Rita has gone to the bank and will be back soon.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>填 been/gone：她不在这儿，She has ___ to the bank.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> gone</p><p><strong>解析：</strong> 按本课规则判断：have been to 表示去过并已返回的经历；have gone to 通常表示去了且尚未返回。谈经验可用现在完成时，补充明确结束的日期或年份时通常改一般过去时。I have been to Rome 与 I went there in 2022 可在一段话中衔接。不能把现在完成时直接与 yesterday 等已结束时间机械拼接。</p></details><p><strong>表达迁移：</strong> 围绕“表达旅行经历并补充具体时间”写两至三句，再读给同伴听。至少使用一次have been to 与过去时间，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rita has gone to the bank and will be back soon. I have been to Vienna twice.</p><p>Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。 Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。</p></details><p><a href="/life/english/new-concept/book-1/unit-04/lesson-086">回看本课</a></p>',60)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
